import{_ as i,l as s,o as e,c as o,v as r,p as n,x as t,d as m,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"RM 集成与不确定性","description":"","frontmatter":{"title":"RM 集成与不确定性","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rm-ensembles.md","filePath":"llm/rm-ensembles.md","lastUpdated":1789023840000}'),p={name:"llm/rm-ensembles.md"};function c(E,a,_,b,f,u){const l=s("Mermaid");return e(),o("div",null,[a[1]||(a[1]=r('<h1 id="rm-集成与不确定性" tabindex="-1">RM 集成与不确定性 <a class="header-anchor" href="#rm-集成与不确定性" aria-label="Permalink to &quot;RM 集成与不确定性&quot;">​</a></h1><div class="epigraph"><p>单个奖励模型给出的是点估计；几份独立拟合的差异，才把「这道完成有多不可信」写进标量。</p><footer>—— Coste 等，Reward Model Ensembles Help Mitigate Overoptimization；对照 Eisenstein 等 Helping or Herding</footer></div><p><a href="/llm/negative-task-vector">上一课</a>把行为改写收在权重空间里的负任务向量：沿一条微调方向反走，抹掉不想要的能力。本课打开「强化学习进阶」。策略不再被一条向量推，而是被一个标量奖励拉。<a href="/llm/reward-model">奖励模型</a> 在 <a href="/llm/rlhf-pipeline">RLHF 流程</a>里被当成真值；它其实是比较数据上的回归器，对分布外完成的方差从未进入 PPO。缺口是：<strong>同一条 \\(y\\)，不同初始化的 RM 会打出差很远的分，策略却只看见均值。</strong> 后课校准、过优化都默认已经读完本课的不确定性。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>InstructGPT 用一份 RM 给 PPO 打分。训练数据是标注员对旧策略样本的排序，测试时策略已经离开那片邻域。Gao、Schulman、Hilton 后来量过：代理奖励继续涨，金标奖励先升后降——过优化。单模型没有内部信号说「我在瞎打」。集成的问题不是再训一个更准的头，而是把 \\(r_\\phi\\) 从点改成分布：\\(\\hat r(x,y)\\) 与 \\(\\hat\\sigma(x,y)\\)，让策略在不确定的区域少走。</p><p>几份 RM 的分歧来自三处：随机种子与数据顺序、比较对的不可传递残差、以及表征对长度/格式捷径的不同敏感度。分歧大，不证明金标低；但分歧小，也不证明金标高——只说明这族模型看法一致。</p><h3 id="集成不是投票选最好的那份" tabindex="-1">集成不是投票选最好的那份 <a class="header-anchor" href="#集成不是投票选最好的那份" aria-label="Permalink to &quot;集成不是投票选最好的那份&quot;">​</a></h3><p>把 \\(K\\) 份 RM 的分数取 \\(\\max\\)，等于把最乐观的黑客面交给策略。取 \\(\\min\\) 过保守，探索停住。主流是均值作奖励、方差作惩罚或门控。Coste 等人表明集成能推迟过优化，不能取消它；Eisenstein 等人进一步问：集成是在帮助，还是只是把策略赶到「所有成员都喜欢」的更窄捷径上（herding）。</p><p><span class="marginnote">成员必须独立训练，或至少独立数据折。对同一 checkpoint 做 dropout 采样，相关太强，\\(\\hat\\sigma\\) 系统性偏小。不要把 LoRA 的几个 rank 当成集成。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数据与损失仍是成对比较，不重写 Bradley-Terry。做 \\(K\\) 份 RM（\\(K\\) 常取 3–8）：不同种子，或把比较对折成 bagging。推理时</p> \\[\\bar r=\\frac1K\\sum_{k} r_{\\phi_k}(x,y),\\qquad \\hat\\sigma^2=\\frac1K\\sum_k\\bigl(r_{\\phi_k}-\\bar r\\bigr)^2. \\]<p>接到 <a href="/llm/ppo-llm">PPO</a> 的标量可以是 \\(\\bar r-\\lambda\\hat\\sigma\\)（pessimism），或仅当 \\(\\hat\\sigma\\) 低于阈值才用 \\(\\bar r\\) 更新。Best-of-N 也可以按 \\(\\bar r-\\lambda\\hat\\sigma\\) 排序。WARM（Rame 等）把成员权重平均，得到一条平滑奖励，显存比 \\(K\\) 次前向便宜，但失去运行时的 \\(\\hat\\sigma\\)。</p>',13)),(e(),n(h,null,{default:t(()=>[d(l,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20CMP%5B%22%E6%AF%94%E8%BE%83%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20K%5B%22K%20%E4%BB%BD%E7%8B%AC%E7%AB%8B%20RM%22%5D%0A%20%20Y%5B%22%E7%AD%96%E7%95%A5%E5%AE%8C%E6%88%90%20y%22%5D%20--%3E%20K%0A%20%20K%20--%3E%20MU%5B%22%E5%9D%87%E5%80%BC%20r%CC%84%22%5D%0A%20%20K%20--%3E%20SG%5B%22%E5%88%86%E6%AD%A7%20%CF%83%CC%82%22%5D%0A%20%20MU%20--%3E%20R%5B%22%E6%82%B2%E8%A7%82%E5%A5%96%E5%8A%B1%20r%CC%84%E2%88%92%CE%BB%CF%83%CC%82%22%5D%0A%20%20SG%20--%3E%20R%0A%20%20R%20--%3E%20PPO%5B%22PPO%20%2F%20Best-of-N%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[m(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>成员初始化自同一 SFT，只改种子，实现便宜，相关偏高；从不同 SFT 或不同比较子集训，相关低、成本高。报告必须写清 \\(K\\)、聚合与 \\(\\lambda\\)，否则「用了集成」不可复现。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>悲观聚合改变的是策略面对的地形：在成员一致的区域，梯度与单 RM 接近；在成员打架的区域，有效奖励被压低，PPO 的正优势变少。于是策略更愿意停留在训练分布附近——这正是推迟 Gao 式过优化的来源。Herding 风险是：捷径（更长、更像清单）若被所有成员学到，方差反而小，悲观项不罚，集成一起被骗。</p><p><span class="marginnote">不确定性是认知的（模型不知），不是随机的（标注噪声）。标注员分歧要另建模，不能指望多训几份 RM 自动吸收。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>\\(K\\) 次 RM 前向在在线 RL 里很贵。可把成员量化、放到推理卡，或只对高分候选算满 \\(K\\) 份。开放域偏好上集成有文献支持；<a href="/llm/verifiable-reward">可验证奖励</a> 的 0/1 没有模型不确定性，本课的 \\(\\hat\\sigma\\) 用不上，应换校验器。集成推迟过优化，下一课问分数的绝对含义是否校准。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>单 RM 是点估计；集成用成员分歧估计对分布外完成的不可信程度。</li><li>聚合用均值减方差惩罚，不要用 max；一致的捷径仍会 herding。</li><li>接到 PPO 或 Best-of-N 时，\\(\\lambda\\) 与 \\(K\\) 必须写入实验卡。</li><li>可验证 0/1 不需要 RM 集成。</li><li>出处：Coste 等 ICLR 2024；Eisenstein 等 COLM 2024；过优化曲线见 Gao, Schulman, Hilton。</li></ul>',8))])}const A=i(p,[["render",c]]);export{g as __pageData,A as default};
